//go:build omugen_engine

package main

import _ "embed" // engine pack

// omugen_engine.zip is generated by tools/packengine (build/omugen_build.sh
// runs it and builds with -tags=omugen_engine).
//
//go:embed omugen_engine.zip
var embeddedEngineZip []byte

// Package-level initialization runs before any init(), so the pack is
// available when dllsearch_windows.go's init loads the runtime DLLs.
var _ = func() bool {
	engineZipData = embeddedEngineZip
	return true
}()
